-- =====================================================================
-- FixMyRide - am_mech schema and seed data
-- Target database : am_mech   (PostgreSQL 18, server "automate")
-- Generated from  : docs/FixMyRide-SRS-HLD-LLD.pdf, section 7.2 (Data design)
--
-- Schema is a faithful port of the LLD tables. SQLite -> PostgreSQL mapping:
--   INTEGER PK AUTOINCREMENT -> INTEGER GENERATED BY DEFAULT AS IDENTITY
--   TEXT                     -> TEXT
--   REAL (money)             -> NUMERIC(10,2)      REAL (rating) -> NUMERIC(2,1)
--   TEXT DEFAULT datetime()  -> TIMESTAMPTZ DEFAULT now()
--   INTEGER 0/1 flags        -> INTEGER (kept as in the LLD, not BOOLEAN)
-- Cross-module columns (mechanic_id in user db, service_request_id in mechanic
-- db, every mirror table in admin db) carry NO foreign key, exactly as the LLD
-- specifies - the three databases stay independently deployable.
--
-- IDs are aligned across all three databases: user #7 is user #7 everywhere,
-- mechanic #12 is mechanic #12 everywhere, and service request #5 is job #5
-- and service_overview #5. This makes the mirrors joinable by hand.
--
-- Contains: mechanics, services, jobs, job_updates, payments, reviews, notifications
-- Each table is seeded with 30 rows. Password for every seeded principal is
-- "password123" (stored as a real bcrypt hash).
--
-- Run with:
--   psql -U postgres -h localhost -d am_mech -f <this file>
-- The script is idempotent: it drops and recreates its own tables.
-- =====================================================================

BEGIN;


-- ---------------------------------------------------------------------
-- 1. SCHEMA
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS job_updates, jobs, services, payments, reviews,
                     notifications, mechanics CASCADE;

CREATE TABLE mechanics (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name            TEXT        NOT NULL,
    email           TEXT        NOT NULL UNIQUE,
    password_hash   TEXT        NOT NULL,
    phone           TEXT,
    skills          TEXT,
    available       INTEGER     NOT NULL DEFAULT 1,
    rating          NUMERIC(2,1) NOT NULL DEFAULT 4.5,
    approval_status TEXT        DEFAULT 'pending',
    workshop_name   TEXT,
    address         TEXT,
    certifications  TEXT,
    pricing_model   TEXT,
    location        TEXT,
    specialization  TEXT,
    price_from      NUMERIC(10,2),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE services (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mechanic_id  INTEGER      NOT NULL REFERENCES mechanics(id) ON DELETE CASCADE,
    name         TEXT         NOT NULL,
    description  TEXT,
    price        NUMERIC(10,2) NOT NULL DEFAULT 0,
    duration     TEXT,
    available    INTEGER      NOT NULL DEFAULT 1,
    is_promotion INTEGER      NOT NULL DEFAULT 0,
    promo_label  TEXT,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- jobs.status defaults to 'assigned': a job only exists once it is dispatched,
-- unlike service_requests which start life as 'pending'.
CREATE TABLE jobs (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_request_id INTEGER     NOT NULL,          -- user module SR, no FK by design
    user_id            INTEGER,
    mechanic_id        INTEGER     NOT NULL REFERENCES mechanics(id) ON DELETE CASCADE,
    category           TEXT,
    description        TEXT,
    status             TEXT        NOT NULL DEFAULT 'assigned'
                       CHECK (status IN ('pending','assigned','accepted',
                                         'in_progress','completed','cancelled')),
    notes              TEXT,
    price              NUMERIC(10,2),
    scheduled_at       TIMESTAMPTZ,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE job_updates (
    id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    job_id     INTEGER     NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    type       TEXT        NOT NULL CHECK (type IN ('note','status_change','image')),
    message    TEXT,
    image_path TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE payments (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    job_id          INTEGER,
    mechanic_id     INTEGER      NOT NULL REFERENCES mechanics(id) ON DELETE CASCADE,
    customer_name   TEXT,
    amount          NUMERIC(10,2) NOT NULL DEFAULT 0,
    method          TEXT,
    status          TEXT         NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','paid','failed','refunded')),
    transaction_ref TEXT,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE reviews (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_request_id INTEGER,
    mechanic_id        INTEGER     NOT NULL,
    user_id            INTEGER,
    user_name          TEXT,
    rating             INTEGER     NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment            TEXT,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE notifications (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    recipient_role TEXT        NOT NULL,
    recipient_id   INTEGER     NOT NULL,
    title          TEXT        NOT NULL,
    body           TEXT        NOT NULL,
    read           INTEGER     NOT NULL DEFAULT 0,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Indexes (LLD section 7.2.4)
CREATE INDEX idx_jobs_mechanic          ON jobs(mechanic_id);
CREATE INDEX idx_services_mechanic      ON services(mechanic_id);
CREATE INDEX idx_payments_mechanic      ON payments(mechanic_id);
CREATE INDEX idx_reviews_mechanic       ON reviews(mechanic_id);
CREATE INDEX idx_jobs_service           ON jobs(service_request_id);
CREATE INDEX idx_job_updates_job        ON job_updates(job_id);
CREATE INDEX idx_notifications_recipient ON notifications(recipient_role, recipient_id);


-- ---------------------------------------------------------------------
-- 2. SEED DATA (30 rows per table)
-- ---------------------------------------------------------------------


