-- reviews ----------------------------------------------------------
-- Identical rows to am_user.reviews so both sides show the same feedback.
INSERT INTO reviews (id, service_request_id, mechanic_id, user_id, user_name,
                     rating, comment, created_at) VALUES
  (1, 1, 3, 1, 'Aarav Sharma', 5, 'Picked up the car on time and explained every line of the bill. Very satisfied.', '2026-01-10 20:37:00+05:30'),
  (2, 2, 7, 2, 'Priya Nair', 4, 'Brake noise is completely gone. Fair pricing and quick turnaround.', '2026-01-17 20:14:00+05:30'),
  (3, 3, 1, 3, 'Rohan Mehta', 3, 'Good work overall, but the car was delivered two hours later than promised.', '2026-01-24 20:51:00+05:30'),
  (4, 4, 12, 4, 'Sneha Iyer', 5, 'Excellent diagnostics. Found a wiring fault two other garages had missed.', '2026-01-31 20:28:00+05:30'),
  (5, 5, 5, 5, 'Vikas Gupta', 5, 'AC is cooling like new again. Would definitely book this mechanic again.', '2026-02-07 20:05:00+05:30'),
  (6, 6, 3, 6, 'Ananya Rao', 4, 'Tyres fitted and balanced properly. Ride quality has improved a lot.', '2026-02-14 20:42:00+05:30'),
  (7, 7, 18, 7, 'Karthik Menon', 5, 'Suspension knock fixed on the first attempt. Clean and professional job.', '2026-02-21 20:19:00+05:30'),
  (8, 8, 9, 8, 'Divya Joshi', 4, 'Reasonable rates and honest advice. Did not push unnecessary replacements.', '2026-02-28 20:56:00+05:30'),
  (9, 9, 1, 9, 'Rahul Verma', 4, 'Clutch feels brand new. Slightly expensive but the quality justifies it.', '2026-03-07 20:33:00+05:30'),
  (10, 10, 22, 10, 'Meera Pillai', 5, 'Service was thorough and the car was returned washed. Great experience.', '2026-03-14 20:10:00+05:30'),
  (11, 11, 7, 11, 'Siddharth Bose', 4, 'Paint match is near perfect. Took an extra day but worth the wait.', '2026-03-21 20:47:00+05:30'),
  (12, 12, 14, 12, 'Neha Kulkarni', 5, 'Alignment sorted the steering pull immediately. Very happy with the result.', '2026-03-28 20:24:00+05:30'),
  (13, 13, 2, 13, 'Arjun Desai', 5, 'Prompt response and transparent estimate shared before starting work.', '2026-04-04 20:01:00+05:30'),
  (14, 14, 25, 14, 'Pooja Reddy', 4, 'Engine runs much smoother now. Mileage has also improved noticeably.', '2026-04-11 20:38:00+05:30'),
